/**
 * Enum-like constants for RTC Agent Protocol
 *
 * These const objects provide type-safe constants for status fields and other categorical values.
 * They are derived from the OpenAPI specification and exported for use across the codebase.
 *
 * ## Relationship with models.gen.ts
 *
 * The OpenAPI spec defines enum types as string literal unions in models.gen.ts:
 * ```typescript
 * // models.gen.ts (auto-generated)
 * export type SessionStatus = 'active' | 'closed' | 'idle';
 * ```
 *
 * This file provides:
 * 1. Runtime values for use in comparisons and switch statements
 * 2. Type definitions that align with the generated types
 *
 * ```typescript
 * // enums.ts (this file)
 * export const SessionStatus = {
 *   Active: 'active',
 *   Closed: 'closed',
 *   Idle: 'idle',
 * } as const;
 * export type SessionStatus = (typeof SessionStatus)[keyof typeof SessionStatus];
 * ```
 *
 * The type `SessionStatus` from this file is compatible with (and assignable to)
 * the type from models.gen.ts, since both resolve to the same string literal union.
 *
 * ## Why not use TypeScript enums?
 *
 * Using const objects with `as const` instead of TypeScript enums ensures:
 * 1. String literal compatibility (values can be used where string literals are expected)
 * 2. Tree-shaking support (unused values are eliminated)
 * 3. Simpler type definitions (no enum nominal type issues)
 * 4. Better IDE autocomplete and refactoring support
 *
 * ## Usage Guidelines
 *
 * - Use the const object for runtime values: `if (status === SessionStatus.Active)`
 * - Use the type for type annotations: `const status: SessionStatus = 'active'`
 * - The generated type and the const object type are interchangeable
 * - Prefer importing from this file over hardcoding string literals
 */


/**
 * Session lifecycle status
 *
 * Defines the state of a session throughout its lifecycle.
 */
export const SessionStatus = {
  /** Session is active and can send/receive messages */
  Active: 'active',
  /** Session is closed and no longer accepts messages */
  Closed: 'closed',
  /** Session is idle due to inactivity */
  Idle: 'idle',
} as const;
export type SessionStatus = (typeof SessionStatus)[keyof typeof SessionStatus];

/**
 * Turn execution status
 *
 * Tracks the lifecycle of a single conversation turn (request-response cycle).
 */
export const TurnStatus = {
  /** Turn is queued but not yet processing */
  Pending: 'pending',
  /** Turn is currently being processed */
  Running: 'running',
  /** Turn completed successfully */
  Completed: 'completed',
  /** Turn failed due to an error */
  Failed: 'failed',
  /** Turn was cancelled by user or system */
  Cancelled: 'cancelled',
  /** Turn was interrupted by a new request */
  Interrupted: 'interrupted',
  /** Turn was merged into another turn */
  Merged: 'merged',
} as const;
export type TurnStatus = (typeof TurnStatus)[keyof typeof TurnStatus];

/**
 * Message author role
 *
 * Identifies who authored a message in the conversation.
 */
export const MessageRole = {
  /** Message from the end user */
  User: 'user',
  /** Message generated by the AI assistant */
  Assistant: 'assistant',
  /** Message from tool execution results */
  Tool: 'tool',
  /** System-level instructions or metadata */
  System: 'system',
} as const;
export type MessageRole = (typeof MessageRole)[keyof typeof MessageRole];

/**
 * Message streaming lifecycle status
 *
 * Tracks the state of message content during streaming.
 */
export const MessageStreamingStatus = {
  /** Content is queued but not yet streaming */
  Pending: 'pending',
  /** Content is actively being streamed */
  Streaming: 'streaming',
  /** Content streaming completed successfully */
  Completed: 'completed',
  /** Content streaming failed */
  Failed: 'failed',
} as const;
export type MessageStreamingStatus =
  (typeof MessageStreamingStatus)[keyof typeof MessageStreamingStatus];

/**
 * Content type for message data
 *
 * Specifies the format and purpose of message content blocks.
 */
export const ContentType = {
  /** Markdown formatted text content */
  Markdown: 'markdown',
  /** Summarized content (condensed view) */
  Summary: 'summary',
  /** Plain text content */
  Text: 'text',
  /** AI thinking/reasoning content */
  Thinking: 'thinking',
  /** Tool call input parameters */
  ToolCallInput: 'toolcall_input',
  /** Tool call execution output */
  ToolCallOutput: 'toolcall_output',
  /** User message content */
  UserMessage: 'user_message',
  /** Error information */
  Error: 'error',
  /** Prompt template content */
  Prompt: 'prompt',
} as const;
export type ContentType = (typeof ContentType)[keyof typeof ContentType];

/**
 * Error classification category
 *
 * Categorizes errors by their source for appropriate handling.
 */
export const ErrorCategory = {
  /** API-related errors (HTTP errors, rate limits) */
  Api: 'api',
  /** Stream-related errors (connection drops, parsing errors) */
  Stream: 'stream',
  /** Tool execution errors */
  Tool: 'tool',
  /** Context-related errors (context window exceeded) */
  Context: 'context',
  /** System-level errors */
  System: 'system',
  /** Network connectivity errors */
  Network: 'network',
  /** Request timeout errors */
  Timeout: 'timeout',
  /** Permission denied errors */
  Permission: 'permission',
} as const;
export type ErrorCategory = (typeof ErrorCategory)[keyof typeof ErrorCategory];

/**
 * Remote tool call execution status
 *
 * Tracks the lifecycle of remote tool execution (Rtc = Remote Tool Call).
 */
export const RtcStatus = {
  /** Tool call is queued locally */
  Pending: 'pending',
  /** Tool call has been sent to remote executor */
  Sent: 'sent',
  /** Tool call is being executed remotely */
  Executing: 'executing',
  /** Tool call completed successfully */
  Completed: 'completed',
  /** Tool call failed during execution */
  Failed: 'failed',
  /** Tool call timed out */
  Timeout: 'timeout',
  /** Tool call was rejected by executor */
  Rejected: 'rejected',
} as const;
export type RtcStatus = (typeof RtcStatus)[keyof typeof RtcStatus];

/**
 * Entity type for update events
 *
 * Identifies which entity type an update event pertains to.
 */
export const UpdateEntity = {
  /** Session entity update */
  Session: 'session',
  /** Turn entity update */
  Turn: 'turn',
  /** Message entity update */
  Message: 'message',
  /** Remote tool call entity update */
  Rtc: 'rtc',
  /** File entity update */
  File: 'file',
} as const;
export type UpdateEntity = (typeof UpdateEntity)[keyof typeof UpdateEntity];

/**
 * Action type for update events
 *
 * Specifies what action was performed on an entity.
 */
export const UpdateAction = {
  /** Entity was newly created */
  Created: 'created',
  /** Existing entity was modified */
  Updated: 'updated',
  /** Entity was deleted */
  Deleted: 'deleted',
} as const;
export type UpdateAction = (typeof UpdateAction)[keyof typeof UpdateAction];

/**
 * Update type (reserved for future use)
 *
 * Reserved for special update types like gap markers.
 */
export const UpdateType = {
  /** Gap marker in update sequence */
  Gap: 'gap',
} as const;
export type UpdateType = (typeof UpdateType)[keyof typeof UpdateType];

/**
 * Todo item status
 *
 * IMPORTANT: This enum is intentionally aligned with the OpenAPI-generated TodoItem.status
 * field values. If the backend API specification is updated, this enum must be updated
 * simultaneously to maintain consistency.
 *
 * Tracks the execution state of task items (aligned with Claude Code TodoItem).
 */
export const TodoStatus = {
  /** Task is queued but not started */
  Pending: 'pending',
  /** Task is currently being executed */
  InProgress: 'in_progress',
  /** Task has been completed */
  Completed: 'completed',
} as const;
export type TodoStatus = (typeof TodoStatus)[keyof typeof TodoStatus];

/**
 * Entity sync status for local persistence
 *
 * Tracks synchronization state for entities stored in IndexedDB (Session/Turn/Message/Rtc).
 */
export const SyncStatus = {
  /** Entity is pending synchronization to remote */
  Pending: 'pending',
  /** Entity has been successfully synchronized */
  Synced: 'synced',
  /** Entity synchronization failed */
  Failed: 'failed',
} as const;
export type SyncStatus = (typeof SyncStatus)[keyof typeof SyncStatus];

/** File sync status lifecycle: pending -> syncing -> synced | failed */
export const FileSyncStatus = {
  Pending: 'pending',
  Syncing: 'syncing',
  Synced: 'synced',
  Failed: 'failed',
} as const;
export type FileSyncStatus =
  (typeof FileSyncStatus)[keyof typeof FileSyncStatus];
